/**
 * GENERIC kit script — do not edit per site (configure via handoff.config.mjs).
 *
 * Vendors everything the live demos need from the prototype into vendor/:
 * token CSS (flattened, in cascade order), fonts, and demo images, per the
 * site's handoff.config.mjs vendor manifest. Also generates vendor/tokens/
 * index.css (@import lines in manifest order) so the theme imports ONE file.
 *
 * On Vercel (subdirectory root) the parent src/ is unavailable — committed
 * vendor copies are used instead.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { basename, dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const siteRoot = join(__dirname, '..')
const repoRoot = join(siteRoot, '../../..')

const { default: config } = await import(join(siteRoot, 'handoff.config.mjs'))
const { roots = {}, tokens = [], fonts = [], images = [], urlRewrites = [] } = config.vendor ?? {}

const tokensRoot = join(repoRoot, roots.tokens ?? 'src/tokens')
const fontsRoot = join(repoRoot, roots.fonts ?? 'src/stores/codm/fonts')
const imagesRoot = join(repoRoot, roots.images ?? 'src/stores/codm/img/content')

const vendorTokens = join(siteRoot, 'vendor/tokens')
const vendorFonts = join(siteRoot, 'vendor/fonts')
const vendorImg = join(siteRoot, 'vendor/img')

mkdirSync(vendorTokens, { recursive: true })

if (!existsSync(tokensRoot)) {
  console.log('[sync-tokens] Prototype src/ not found — using committed vendor copies.')
  // Still (re)generate index.css from the manifest so theme imports stay valid.
  writeIndexCss()
  process.exit(0)
}

mkdirSync(vendorFonts, { recursive: true })
mkdirSync(vendorImg, { recursive: true })

for (const rel of tokens) {
  const src = join(tokensRoot, rel)
  const base = basename(rel)
  if (!existsSync(src)) { console.warn(`[sync-tokens] Skip missing: ${src}`); continue }
  let css = readFileSync(src, 'utf8')
  for (const rw of urlRewrites) {
    if (rw.in === base) css = css.split(rw.from).join(rw.to)
  }
  writeFileSync(join(vendorTokens, base), css)
  console.log(`[sync-tokens] tokens/${base}`)
}
writeIndexCss()

copyAll(fonts, fontsRoot, vendorFonts, 'fonts')
copyAll(images, imagesRoot, vendorImg, 'img')

function writeIndexCss() {
  const lines = tokens.map((rel) => `@import './${basename(rel)}';`)
  writeFileSync(
    join(vendorTokens, 'index.css'),
    `/* GENERATED by scripts/sync-tokens.mjs — cascade order from handoff.config.mjs */\n${lines.join('\n')}\n`,
  )
  console.log('[sync-tokens] tokens/index.css (generated)')
}

function copyAll(files, srcRoot, destRoot, label) {
  for (const f of files) {
    const src = join(srcRoot, f)
    if (!existsSync(src)) { console.warn(`[sync-tokens] Skip missing ${label}: ${f}`); continue }
    copyFileSync(src, join(destRoot, basename(f)))
    console.log(`[sync-tokens] ${label}/${basename(f)}`)
  }
}
